function setCellWeight(content, cellName, weight) {
    var re = new RegExp('(this\\.' + cellName + '\\.[\\s\\S]*?\\.Weight = )([0-9.]+D);', 'm');
    if (!re.test(content)) {
        throw new Error('Weight not found for ' + cellName);
    }
    return content.replace(re, '$1' + weight + ';');
}

function patchCommon(content) {
    content = content.replace(/this\.table1\.LocationFloat = new DevExpress\.Utils\.PointFloat\(10\.99999F, 0F\);/g,
        'this.table1.LocationFloat = new DevExpress.Utils.PointFloat(11F, 0F);');
    content = content.replace(/new System\.Drawing\.Font\("Times New Roman", 12F/g,
        'new System.Drawing.Font("Times New Roman", 10F');
    content = content.replace(/this\.table2\.Font = new System\.Drawing\.Font\("Times New Roman", 9F, System\.Drawing\.FontStyle\.Bold\);/g,
        'this.table2.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);');
    content = content.replace(/this\.tableRow2\.Font = new System\.Drawing\.Font\("Times New Roman", 10F, System\.Drawing\.FontStyle\.Bold\);/g,
        'this.tableRow2.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);');
    return content;
}

function patchTinChi(filePath) {
    var content = fs.readFileSync(filePath, 'utf8');
    content = patchCommon(content);
    for (var cell in tinChiHeaderWeights) {
        content = setCellWeight(content, cell, tinChiHeaderWeights[cell]);
    }
    content = setCellWeight(content, 'tableCell53', tinChiDetailPersonWeight);
    fs.writeFileSync(filePath, content, 'utf8');
    console.log('Fixed TinChi: ' + filePath);
}

function patchNienChe(filePath) {
    var content = fs.readFileSync(filePath, 'utf8');
    content = patchCommon(content);
    for (var cell in nienCheHeaderWeights) {
        content = setCellWeight(content, cell, nienCheHeaderWeights[cell]);
    }
    content = setCellWeight(content, 'tableCell57', nienCheDetailPersonWeight);
    fs.writeFileSync(filePath, content, 'utf8');
    console.log('Fixed NienChe: ' + filePath);
}

